} from './lib/missionControl';
import { buildTerminalWsUrl, getTerminalConnectionInfo, getTerminalPortCandidates, rememberTerminalPort } from './lib/terminalBridge';

function retryableLazy(load, selectModule = module => module) {
    let loadFailed = false;
    let failure;
    let retries = 0;
    const createComponent = () => lazy(() => {
        const retryUrl = lazyModuleRetryUrl(failure, import.meta.url, retries);
        return (retryUrl ? import(/* @vite-ignore */ retryUrl) : load())
            .then(selectModule)
            .catch(error => { loadFailed = true; if (!failure) failure = error; throw error; });
    });
    let Component = createComponent();
    return function LazyMode(props) {
        const [attempt, setAttempt] = useState(0);
        return <WindowErrorBoundary key={attempt} onRetry={() => { if (loadFailed) { loadFailed = false; retries = Math.min(3, retries + 1); Component = createComponent(); } setAttempt(value => value + 1); }}>
            <Suspense fallback={<div role="status" className="p-6 text-[var(--text-secondary)]">Loading…</div>}>
                <Component {...props} />
            </Suspense>
        </WindowErrorBoundary>;
    };
}

class ModeErrorBoundary extends Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null };
    }
    static getDerivedStateFromError(error) {
        return { hasError: true, error };
    }
    componentDidCatch(error, info) {
        console.error('[ModeErrorBoundary] Mode render error:', error, info);
    }
    render() {
        if (this.state.hasError) {
            return (
                <div className="flex h-full flex-col items-center justify-center gap-4 p-8 text-center">
                    <div className="rounded-xl border border-red-500/30 bg-red-500/10 p-6 max-w-lg w-full">
                        <p className="text-sm font-semibold text-red-400 mb-2">Page failed to render</p>
                        <p className="font-mono text-xs text-red-300/80 break-all leading-5">
                            {this.state.error?.message || 'An unexpected error occurred.'}
                        </p>
                        {this.state.error?.stack && (
                            <pre className="mt-3 text-left text-[10px] text-red-300/60 overflow-auto max-h-48 leading-4">
                                {this.state.error.stack}
                            </pre>
                        )}
                        <button
                            onClick={() => this.setState({ hasError: false, error: null })}
                            className="mt-4 rounded-lg border border-red-500/40 px-4 py-1.5 text-xs text-red-300 hover:bg-red-500/10 transition-colors"
                        >
                            Retry
                        </button>
                    </div>
                </div>
            );
        }
        return this.props.children;
    }
}

function AppContent() {
    const appVisible = useAppVisibility();
    const [startupFailures, setStartupFailures] = useState([]);
    const gatewayRequestRef = useRef(null);
    useEffect(() => {
        let active = true;
        const policy = readPerformancePolicy();
        for (const id of Object.keys(AUTOMATIC_SERVICES)) {
            if (shouldAutoStartService(policy, id, 'startup') && window.electron) {
                Promise.resolve().then(() => startIntegrationService(id)).then(result => {
                    if (result?.ok === false || result?.error) throw new Error('Service unavailable');
                }).catch(() => {
                    if (active) setStartupFailures(current => current.includes(id) ? current : [...current, id]);
                });
            }
        }
        return () => { active = false; };
    }, []);
    const {
        currentMode,
        setCurrentMode,
        windows,
        openWindow,
        youtubeUrl,
        showGlobalTerminal,
        setShowGlobalTerminal,
        openClawConfig,
        showChatGuide,
        setShowChatGuide,
        cycleWindows
    } = useMode();
    const openClawWindowOpen = windows.some(w => w.id === OPENCLAW_WINDOW_ID && w.state !== 'minimized');
    const hermesWindowOpen = windows.some(w => w.id === HERMES_WINDOW_ID && w.state !== 'minimized');
    const skillsWindowOpen = windows.some(w => w.id === SKILLS_WINDOW_ID && w.state !== 'minimized');
    const packagesWindowOpen = windows.some(w => w.id === PACKAGES_WINDOW_ID && w.state !== 'minimized');
    const agentmailWindowOpen = windows.some(w => w.id === AGENTMAIL_WINDOW_ID && w.state !== 'minimized');
    const autoforgeWindowOpen = windows.some(w => w.id === AUTOFORGE_WINDOW_ID && w.state !== 'minimized');

    const perciDeskOpen = windows.some(w => w.modeId === MODES.PERCI_DESK && w.state !== 'minimized');
    const { isDarkMode, themeMode, cycleThemeMode } = useTheme();
    const { isIncognitoMode, toggleIncognitoMode, createNewChat } = useChat();
    const [openClawStatus, setOpenClawStatus] = useState({ state: 'idle' });
    const [openClawFrameKey, setOpenClawFrameKey] = useState(0);
    const [openClawDashboardIssue, setOpenClawDashboardIssue] = useState(null);
    const [isRestartingOpenClaw, setIsRestartingOpenClaw] = useState(false);
    const [showModeGuide, setShowModeGuide] = useState(false);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [dockAutoHide, setDockAutoHide] = useState(() => readStringStorage('perci_dock_autohide', 'false') === 'true');
    const [terminalCommand, setTerminalCommand] = useState('');
    const [updaterState, setUpdaterState] = useState(null);
    const [openClawDashboardTab, setOpenClawDashboardTab] = useState('chat');
    // Always land on the native Chat tab when the OpenClaw window (re)opens, so
    // switching to Models/Diary/Dashboard never "sticks" as the default view.
    const wasOpenClawOpenRef = useRef(false);
    useEffect(() => {
        if (openClawWindowOpen && !wasOpenClawOpenRef.current) {
            setOpenClawDashboardTab('chat');
        }
        wasOpenClawOpenRef.current = openClawWindowOpen;
    }, [openClawWindowOpen]);
    const [diaryContent, setDiaryContent] = useState('');
    const [diaryLastSaved, setDiaryLastSaved] = useState(null);
    const [diarySaving, setDiarySaving] = useState(false);
    const diaryAutoSaveRef = useRef(null);
    const openClawWebviewRef = useRef(null);
    const activeOpenClawProfile = useMemo(
        () => openClawConfig.profiles.find(profile => profile.id === openClawConfig.activeProfileId) || openClawConfig.profiles[0],
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [openClawConfig.activeProfileId, openClawConfig.profiles]
    );
    const activeOpenClawDashboardUrl = useMemo(
        () => getOpenClawDashboardUrl(activeOpenClawProfile),
        [activeOpenClawProfile]
    );

    useEffect(() => {
        const frame = window.requestAnimationFrame(() => {
            window.dispatchEvent(new Event('resize'));
        });
        return () => window.cancelAnimationFrame(frame);
    }, [dockAutoHide]);

    useEffect(() => {
        if (window.electron?.onUpdaterState) {
            return window.electron.onUpdaterState((state) => setUpdaterState(state));
        }
    }, []);

    // TEMPORARY diagnostic for the stray same-origin top-frame navigation
    // that main.cjs's `blocked-self-navigation` guard intercepts but never
    // identified a source for. document.activeElement at the moment a
    // navigation begins is almost always the element that triggered it
    // (click gives focus, or it's the submitting form control). Remove once
    // the trigger is found and fixed.
    useEffect(() => {
        const logStrayNavigation = () => {
            const el = document.activeElement;
            // eslint-disable-next-line no-console
            console.error('[stray-navigation] activeElement at unload:', el?.outerHTML?.slice(0, 400) || el?.tagName || 'none');
        };
        window.addEventListener('beforeunload', logStrayNavigation);
        return () => window.removeEventListener('beforeunload', logStrayNavigation);
    }, []);

    // Listen for Electron Menu Actions
    useEffect(() => {
        if (window.electron && window.electron.onMenuAction) {
            window.electron.onMenuAction((action) => {
                console.log('Menu action received:', action);
                switch (action) {
                    case 'new-chat':
                        setCurrentMode(MODES.CHAT); // opens/focuses the Chat window
                        createNewChat();
                        break;
                    case 'switch-mode-chat':
                        setCurrentMode(MODES.CHAT);
                        break;
                    case 'switch-mode-cowork':
                        setCurrentMode(MODES.COWORK);
                        break;
                    case 'switch-mode-mission':
                        setCurrentMode(MODES.MISSION);
                        break;
                    case 'switch-mode-code':
                        setCurrentMode(MODES.CODE);
                        break;
                    case 'choose-folder':
                        // This will trigger the folder selection logic
                        // We can either emit an event or handle it in some specialized context
                        document.dispatchEvent(new CustomEvent('trigger-choose-folder'));
                        break;
                    case 'cycle-next-window':
                        cycleWindows('forward');
                        break;
                    case 'cycle-prev-window':
                        cycleWindows('backward');
                        break;
                    default:
                        break;
                }
            });
        }
    }, [setCurrentMode, createNewChat, cycleWindows]);

    useEffect(() => {
        if (!activeOpenClawProfile) return;
        let cancelled = false;
        let timer;

        async function testOpenClaw() {
            try {
                let result;
                if (!window.electron?.testOpenClawConnection) {
                    result = { ok: false, error: 'OpenClaw Gateway checks require the desktop app.' };
                } else {
                    // Visibility changes join a pending check for the same profile.
                    // They do not start another native request while it is settling.
                    if (gatewayRequestRef.current?.profile !== activeOpenClawProfile) {
                        const request = { profile: activeOpenClawProfile };
                        request.promise = (async () => {
                            const next = await window.electron.testOpenClawConnection(activeOpenClawProfile);
                            if (next.ok && window.electron?.getOpenClawGatewayStatus) {
                                try {
                                    const status = await window.electron.getOpenClawGatewayStatus(activeOpenClawProfile);
                                    if (status?.ok && status.health) next.health = status.health;
                                } catch { /* keep the reachability verdict */ }
                            }
                            return next;
                        })().finally(() => {
                            if (gatewayRequestRef.current === request) gatewayRequestRef.current = null;
                        });
                        gatewayRequestRef.current = request;
                    }
                    result = await gatewayRequestRef.current.promise;
                }
                if (!cancelled) {
                    const checkedAt = new Date().toISOString();
                    setOpenClawStatus({ state: result.ok ? 'online' : 'offline', result, checkedAt });
                    recordGatewayCheck(activeOpenClawProfile, result, 'automatic check');
                }
            } catch {
                if (!cancelled) setOpenClawStatus({ state: 'offline', checkedAt: new Date().toISOString() });
            } finally {
                if (!cancelled) timer = setTimeout(testOpenClaw, appVisible ? 30000 : 120000);
            }
        }

        setOpenClawStatus({ state: 'checking', checkedAt: new Date().toISOString() });
        void testOpenClaw();
        return () => { cancelled = true; clearTimeout(timer); };
    }, [activeOpenClawProfile, appVisible]);

    useEffect(() => {
        setOpenClawDashboardIssue(null);
    }, [activeOpenClawProfile?.id, activeOpenClawDashboardUrl, openClawFrameKey]);

    const openOpenClawDashboard = () => {
        if (!activeOpenClawDashboardUrl) return;
        setOpenClawDashboardIssue(null);
        openWindow(OPENCLAW_WINDOW_ID);
    };

    const openOpenClawExternally = () => {
        if (!activeOpenClawDashboardUrl) return;
        if (window.electron?.openExternal) {
            window.electron.openExternal(activeOpenClawDashboardUrl);
        } else {
            window.open(activeOpenClawDashboardUrl, '_blank', 'noopener,noreferrer');
        }
    };

    const openOpenClawRepo = () => {
        const url = 'https://github.com/openclaw/openclaw';
        if (window.electron?.openExternal) {
            window.electron.openExternal(url);
        } else {
            window.open(url, '_blank', 'noopener,noreferrer');
        }
    };

    const restartOpenClawGateway = async () => {
        if (!window.electron?.restartOpenClawGateway || isRestartingOpenClaw) return;
        setIsRestartingOpenClaw(true);
        setOpenClawDashboardIssue(null);
        setOpenClawStatus({ state: 'checking', checkedAt: new Date().toISOString() });
        recordGatewayRestart(activeOpenClawProfile, { ok: true }, 'started');
        const result = await window.electron.restartOpenClawGateway();
        if (!result?.ok) {
            const checkedAt = new Date().toISOString();
            setOpenClawStatus({
                state: 'offline',
                result: { ok: false, error: result?.error || 'Failed to restart OpenClaw Gateway.' },
                checkedAt
            });
            recordGatewayRestart(activeOpenClawProfile, result, 'completed');
            setIsRestartingOpenClaw(false);
            return;
        }
        recordGatewayRestart(activeOpenClawProfile, result, 'completed');

        // Poll until the gateway is live (up to 12 s) then reload the webview.
        // 1.5 s was often too short; the gateway needs 2-4 s to fully bind.
        const maxWaitMs = 12000;
        const pollMs = 800;
        const started = Date.now();
        const pollUntilLive = async () => {
            const status = await window.electron.testOpenClawConnection(activeOpenClawProfile);
            if (status.ok || Date.now() - started >= maxWaitMs) {
                const checkedAt = new Date().toISOString();
                setOpenClawStatus({ state: status.ok ? 'online' : 'offline', result: status, checkedAt });
                recordGatewayCheck(activeOpenClawProfile, status, 'post-restart poll');
                setOpenClawFrameKey(key => key + 1);
                setIsRestartingOpenClaw(false);
            } else {
                setTimeout(pollUntilLive, pollMs);
            }
        };
        setTimeout(pollUntilLive, pollMs);
    };

    // Supplies the UI for each windowed mode. Mission Control needs live props,
    // so window content is rendered here rather than inside the window layer.
    // OpenClaw renders as a window (webview-backed). Reuses the dashboard
    // toolbar/tabs/content that previously lived in a fullscreen overlay.
    const renderOpenClawWindow = () => (
        <div className="flex h-full flex-col bg-[var(--bg-primary)] oc-window">
                            <div className="h-11 shrink-0 flex items-center justify-between gap-3 px-4 border-b border-[var(--border)] bg-[var(--bg-secondary)]">
                                <div className="min-w-0 flex items-center gap-2">
                                    <Server size={15} className={openClawStatus.state === 'online' ? 'text-emerald-500' : 'text-[var(--text-tertiary)]'} />
                                    <div className="min-w-0">
                                        <div className="text-sm font-semibold text-[var(--text-primary)] truncate">
                                            {activeOpenClawProfile.name}
                                        </div>
                                        {openClawDashboardTab !== 'chat' && (
                                            <div className="text-[11px] font-mono text-[var(--text-tertiary)] truncate">
                                                {activeOpenClawProfile.controlUrl}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {openClawDashboardTab === 'gateway' && (
                                    <form onSubmit={handleTerminalSubmit} className="flex-1 max-w-md mx-8 relative">
                                        <div className="relative flex items-center">
                                            <span className="absolute left-2.5 text-[var(--text-tertiary)] font-mono text-xs select-none">$</span>
                                            <input
                                                type="text"
                                                value={terminalCommand}
                                                onChange={(e) => setTerminalCommand(e.target.value)}
                                                placeholder="Send command to terminal..."
                                                className="w-full pl-6 pr-12 py-1 text-xs font-mono rounded-lg border border-[var(--border)] bg-[var(--bg-primary)] text-[var(--text-primary)] placeholder-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] transition-all"
                                            />
                                            <button
                                                type="submit"
                                                className="absolute right-1 px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider bg-[var(--bg-secondary)] hover:bg-[var(--bg-hover)] text-[var(--text-secondary)] border border-[var(--border)] transition-colors"
                                            >
                                                Run
                                            </button>
                                        </div>
                                    </form>
                                )}
                                {openClawDashboardTab === 'diary' && (
                                    <div className="flex-1 mx-8 flex items-center justify-center">
                                        <span className="text-xs text-[var(--text-tertiary)] italic">
                                            {diarySaving ? 'Saving…' : diaryLastSaved ? `Saved ${diaryLastSaved.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : 'Not yet saved'}
                                        </span>
                                    </div>
                                )}

                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={openOpenClawRepo}
                                        className="hidden sm:inline-flex items-center gap-1 px-2 py-1.5 rounded-md text-[11px] text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
                                        title="OpenClaw is open-source (MIT) — view on GitHub"
                                    >
                                        Powered by OpenClaw
                                        <ExternalLink size={11} />
                                    </button>
                                    {openClawDashboardTab !== 'chat' && (
                                        <span className={`hidden sm:inline text-xs ${openClawStatus.state === 'online' ? 'text-emerald-500' : openClawStatus.state === 'checking' ? 'text-[var(--text-secondary)]' : 'text-red-400'}`}>
                                            {openClawStatus.state === 'online'
                                                ? 'Gateway reachable'
                                                : openClawStatus.state === 'checking'
                                                    ? 'Checking...'
                                                    : 'Gateway unreachable'}
                                        </span>
                                    )}
                                    {openClawDashboardTab === 'gateway' && (
                                        <button
                                            onClick={() => {
                                                setOpenClawDashboardIssue(null);
                                                setOpenClawFrameKey(key => key + 1);
                                            }}
                                            className="p-1.5 rounded-md text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
                                            title="Reload dashboard"
                                        >
                                            <RefreshCw size={16} />
                                        </button>
                                    )}
                                    {window.electron?.restartOpenClawGateway && activeOpenClawProfile?.mode === 'local' && (
                                        <button
                                            onClick={restartOpenClawGateway}
                                            disabled={isRestartingOpenClaw}
                                            className="px-2 py-1.5 rounded-md text-xs font-medium text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] disabled:opacity-50 transition-colors"
                                            title="Restart local OpenClaw Gateway"
                                        >
                                            {isRestartingOpenClaw ? 'Restarting...' : 'Restart Gateway'}
                                        </button>
                                    )}
                                    <button
                                        onClick={openOpenClawExternally}
                                        className="p-1.5 rounded-md text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
                                        title="Open in browser"
                                    >
                                        <ExternalLink size={16} />
                                    </button>
                                </div>
                            </div>
                            {/* Tab strip */}
                            <div className="shrink-0 flex items-center border-b border-[var(--border)] bg-[var(--bg-secondary)] px-2">
                                {[
                                    { id: 'chat', label: 'Chat', icon: <MessageSquare size={12} /> },
                                    { id: 'models', label: 'Models', icon: <Cpu size={12} /> },
                                    { id: 'diary', label: "User's Diary", icon: <BookOpen size={12} /> },
                                    { id: 'gateway', label: 'Dashboard', icon: <Server size={12} /> },
                                ].map(tab => (
                                    <button
                                        key={tab.id}
                                        onClick={() => setOpenClawDashboardTab(tab.id)}
                                        className={`flex items-center gap-1.5 px-3 py-2 text-xs font-medium border-b-2 -mb-px transition-colors ${
                                            openClawDashboardTab === tab.id
                                                ? 'border-[var(--accent)] text-[var(--accent)]'
                                                : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)]'
                                        }`}
                                    >
                                        {tab.icon}
                                        {tab.label}
                                    </button>
                                ))}
                            </div>

                            {openClawDashboardTab === 'chat' ? (
                                <OpenClawChatPanel
                                    profile={activeOpenClawProfile}
                                    status={openClawStatus}
                                    isRestarting={isRestartingOpenClaw}
                                    onRestart={activeOpenClawProfile?.mode === 'local' && window.electron?.restartOpenClawGateway ? restartOpenClawGateway : null}
                                />
                            ) : openClawDashboardTab === 'models' ? (
                                <OpenClawModelsPanel />
                            ) : openClawDashboardTab === 'diary' ? (
                                <div className="flex-1 min-h-0 flex flex-col bg-[var(--bg-primary)]">
                                    <div className="flex-1 min-h-0 relative">
                                        <textarea
                                            value={diaryContent}
                                            onChange={e => handleDiaryChange(e.target.value)}
                                            placeholder={`Write anything you'd like OpenClaw to know about you — your thoughts, goals, current projects, preferences, reflections…\n\nOpenClaw reads this daily to get deeper context about who you are and what matters to you.`}
                                            className="absolute inset-0 w-full h-full resize-none p-6 bg-[var(--bg-primary)] text-[var(--text-primary)] text-sm leading-7 outline-none placeholder-[var(--text-tertiary)] font-[inherit]"
                                            spellCheck
