                                                    <RefreshCw size={15} className={isRestartingOpenClaw ? 'animate-spin' : ''} />
                                                    {isRestartingOpenClaw ? 'Restarting Gateway...' : 'Restart Gateway'}
                                                </button>
                                            )}
